B.asL=new A.ab("lib/core/config.dart dosyas\u0131n\u0131 a\xe7\u0131p Supabase Project URL ve anon anahtar\u0131n\u0131 yap\u0131\u015ft\u0131r, sonra uygulamay\u0131 yeniden ba\u015flat.",null,null,B.S,null,null,null,null,null,null)
